public sealed class DocumentaryProductionCertificationPolicy
{
    public DocumentaryProductionCertificationPolicy(bool requireCertifiedKnowledgeFoundation=true,bool requireCompleteExportMaterialization=true,bool requireCompleteMediaProjection=true,bool requireCompletePipelineExecution=true,bool requireFourVerifiedVariants=true,bool requireExactIdentityChain=true,bool requireExactCorrelationChain=true,bool requireExactProvenanceChain=true,bool requireExactTopicChain=true,bool requireKnowledgeTraceability=true,bool requireNarrationTraceability=true,bool requireSubtitleTraceability=true,bool requireVisualTraceability=true,bool requireSceneAssetTraceability=true,bool requireDeterminism=true,bool requireNonMutation=true,bool requireSerializationStability=true,bool requireArchitectureBoundaryCompliance=true,bool requireDocumentationCompliance=true,IReadOnlyList<DocumentaryMediaVariantType>? requiredVariantTypes=null,string certificationSchemaVersion="1.0")
    {
        var controls=new[]{requireCertifiedKnowledgeFoundation,requireCompleteExportMaterialization,requireCompleteMediaProjection,requireCompletePipelineExecution,requireFourVerifiedVariants,requireExactIdentityChain,requireExactCorrelationChain,requireExactProvenanceChain,requireExactTopicChain,requireKnowledgeTraceability,requireNarrationTraceability,requireSubtitleTraceability,requireVisualTraceability,requireSceneAssetTraceability,requireDeterminism,requireNonMutation,requireSerializationStability,requireArchitectureBoundaryCompliance,requireDocumentationCompliance};
        if(controls.Any(x=>!x)) throw new ArgumentException("Schema 1.0 requires every control.");
        RequiredVariantTypes=DocumentaryProductionCertificationInventory.Copy(requiredVariantTypes??DocumentaryProductionCertificationInventory.VariantTypes);
        if(!RequiredVariantTypes.SequenceEqual(DocumentaryProductionCertificationInventory.VariantTypes))throw new ArgumentException("Canonical variants required.");
        CertificationSchemaVersion=certificationSchemaVersion=="1.0"?certificationSchemaVersion:throw new ArgumentException("Schema must be 1.0.");
        RequireCertifiedKnowledgeFoundation=requireCertifiedKnowledgeFoundation;RequireCompleteExportMaterialization=requireCompleteExportMaterialization;RequireCompleteMediaProjection=requireCompleteMediaProjection;RequireCompletePipelineExecution=requireCompletePipelineExecution;RequireFourVerifiedVariants=requireFourVerifiedVariants;RequireExactIdentityChain=requireExactIdentityChain;RequireExactCorrelationChain=requireExactCorrelationChain;RequireExactProvenanceChain=requireExactProvenanceChain;RequireExactTopicChain=requireExactTopicChain;RequireKnowledgeTraceability=requireKnowledgeTraceability;RequireNarrationTraceability=requireNarrationTraceability;RequireSubtitleTraceability=requireSubtitleTraceability;RequireVisualTraceability=requireVisualTraceability;RequireSceneAssetTraceability=requireSceneAssetTraceability;RequireDeterminism=requireDeterminism;RequireNonMutation=requireNonMutation;RequireSerializationStability=requireSerializationStability;RequireArchitectureBoundaryCompliance=requireArchitectureBoundaryCompliance;RequireDocumentationCompliance=requireDocumentationCompliance;
    }
    public bool RequireCertifiedKnowledgeFoundation{get;} public bool RequireCompleteExportMaterialization{get;} public bool RequireCompleteMediaProjection{get;} public bool RequireCompletePipelineExecution{get;} public bool RequireFourVerifiedVariants{get;} public bool RequireExactIdentityChain{get;} public bool RequireExactCorrelationChain{get;} public bool RequireExactProvenanceChain{get;} public bool RequireExactTopicChain{get;} public bool RequireKnowledgeTraceability{get;} public bool RequireNarrationTraceability{get;} public bool RequireSubtitleTraceability{get;} public bool RequireVisualTraceability{get;} public bool RequireSceneAssetTraceability{get;} public bool RequireDeterminism{get;} public bool RequireNonMutation{get;} public bool RequireSerializationStability{get;} public bool RequireArchitectureBoundaryCompliance{get;} public bool RequireDocumentationCompliance{get;} public IReadOnlyList<DocumentaryMediaVariantType> RequiredVariantTypes{get;} public string CertificationSchemaVersion{get;}
}
